  const lines = raw.split(/\r?\n/).filter((l) => l.trim().length > 0);
  if (lines.length === 0) return [];
  const headers = lines[0].split(",");
  const rows: string[][] = [headers];
  for (let i = 1; i < lines.length; i += 1) {
    rows.push(lines[i].split(","));
  }
  return rows;
}

