function copyTemplate(srcFile, targetRoot, relDest) {
  const rootAbs = path.resolve(targetRoot);
  const outPath = path.resolve(rootAbs, relDest);
  const rel = path.relative(rootAbs, outPath);
  if (!rel || rel.startsWith("..") || path.isAbsolute(rel)) {
    throw new Error(`Invalid target path: ${relDest}`);
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  const text = fs.readFileSync(srcFile, "utf8").replace(/^\uFEFF/, "").replace(/\r\n/g, "\n");
  fs.writeFileSync(outPath, text, "utf8");
  if (outPath.endsWith(".sh")) fs.chmodSync(outPath, 0o755);
  return outPath;
}

