import { useState } from "react";
export type RuleAction = { kind: "rate"; limit: number } | { kind: "block"; reason: string };
export interface Rule { id: string; threshold: number; actions: RuleAction[]; }

export function EditRuleModal({ rule, open, onSave }: { rule: Rule; open: boolean; onSave: (r: Rule) => void }) {
  const [threshold, setThreshold] = useState(rule.threshold);
  if (!open) return null;
  const rateLimits: number[] = rule.actions.filter((a) => a.kind === "rate").map((a) => a.limit);
  return (<div><input type="number" value={threshold} onChange={(e) => setThreshold(Number(e.target.value))} /><button onClick={() => onSave({ ...rule, threshold })}>保存</button><span>{rateLimits.join(",")}</span></div>);
}

